#!/usr/bin/env python3
"""School Select - Mdares-style components installer.
Run from your school-select repo root: python3 install.py
"""
import os, sys, base64, gzip, json

MANIFEST = {
  "src/components/school/StickyContactBar.tsx": "",
  "src/components/school/SchoolHero.tsx": "",
  "src/components/school/SchoolRelated.tsx": "",
  "src/components/school/SchoolContact.tsx": "",
  "src/components/school/SchoolFAQ.tsx": "",
  "src/components/school/SchoolAbout.tsx": "",
  "src/components/school/SchoolGoogleReviews.tsx": "",
  "src/components/school/SchoolEvents.tsx": "",
  "src/components/school/SchoolFeesAndFacilities.tsx": "",
  "src/components/school/SchoolGallery.tsx": "",
  "src/components/layout/Breadcrumb.tsx": "",
  "src/app/ecole/[slug]/page.tsx": "",
  "src/styles/tokens-mdares-aliases.css": "H4sIANBG7GkC/9PXUvBNSSxKLVZIzMlMLAbSjxqmKCQWFKTmpSgkliiAqPw0Baui/PwShcw8hZL87NS8Yr3k4mIFLX0uiHA1l4KCrm5BUWZuYlGllUJZYpGGrm4u2FSYqKY1WE1xanJ+XgqmKrg4VF1+Wlp5RmZJKpqypHS4DFBhLRcAeXX2mr0AAAA="
}

def main():
    if not os.path.exists('package.json'):
        print('ERROR: run from repo root (no package.json found)')
        sys.exit(1)
    
    for path, encoded in MANIFEST.items():
        os.makedirs(os.path.dirname(path), exist_ok=True)
        data = gzip.decompress(base64.b64decode(encoded))
        with open(path, 'wb') as f:
            f.write(data)
        print(f'OK {path}')
    
    print()
    print(f'{len(MANIFEST)} files installed.')
    print()
    print('Next steps:')
    print('  1. Append /src/styles/tokens-mdares-aliases.css content into tokens.css')
    print('  2. npx tsc --noEmit')
    print('  3. npm run dev  -> http://localhost:3000/ecole/les-nouvelles-generations-djerba')

if __name__ == "__main__":
    main()
